\label{thm:intro-principle}
Let $\gamma\in(0,1]$, and suppose that every $p$-harmonic function in every ball of $\mathbb R^n$ belongs locally to $C^{1,\gamma}$. Then, for every $\beta\in(0,\gamma)$, there is $C=C(n,p,\gamma,\beta)<\infty$ such that every $p$-harmonic function $u$ in $B_1$ satisfies
\begin{equation}\label{eq:intro-main-estimate}
\left\lVert Du\right\rVert_{L^\infty(B_{1/2})}+[Du]_{C^{0,\beta}(B_{1/2})}
\le C\left\lVert u\right\rVert_{L^\infty(B_{3/4})}.
\end{equation}
The constant $C$ is independent of $u$.

\label{cor:intro-planar}
Let $u$ be $p$-harmonic in $B_1 \subset \mathbb R^2$. For every $0<\beta<\alpha_{\mathrm{IM}}(p)$, there is $C=C(p,\beta)<\infty$ such that
\begin{equation}\label{eq:intro-planar-Lp}
\left\lVert u\right\rVert_{C^{1,\beta}(B_{1/2})}\le C(p,\beta)\left\lVert u\right\rVert_{L^p(B_1)}.
\end{equation}

\label{thm:planar-critical-almost-endpoint}
For every $\beta\in(0,1/3)$ there is $C_\beta<\infty$ such that every infinity-harmonic function $u$ in $B_1\subset\mathbb R^2$ satisfies
\begin{equation}\label{eq:planar-uniform-gradient}
\left\lVert Du\right\rVert_{L^\infty(B_{1/2})}+[Du]_{C^{0,\beta}(B_{1/2})}
\le C_\beta\operatorname*{osc}_{B_{3/4}}u.
\end{equation}
The constant depends only on $\beta$.

\label{thm:nonlocal-conditional}
Let $s\in(1/2,1)$, and suppose that every viscosity solution $v\in C(B)\cap L_s^1(\mathbb R^n)$ of $\left\lvert Dv\right\rvert(-\Delta)^sv=0$ in a ball $B$ is Fr\'echet differentiable at every point of $B$. Then, there are $\alpha=\alpha(n,s)\in(0,2s-1)$ and $C=C(n,s)<\infty$ such that every viscosity solution $u\in L^\infty(\mathbb R^n)\cap C(B_1)$ of \eqref{eq:scalar-nonlocal} satisfies
\begin{equation}\label{eq:nonlocal-conditional-estimate}
\left\lVert Du\right\rVert_{L^\infty(B_{1/2})}+[Du]_{C^{0,\alpha}(B_{1/2})}\le C\left\lVert u\right\rVert_{L^\infty(\mathbb R^n)}.
\end{equation}
The constants are independent of $u$.

\label{lem:equivalence}
Let $q\in\mathbb R^n$ and $v\in C(\Omega)$. The following are equivalent:
\begin{enumerate}
  \item $v$ is a viscosity solution of $\mathcal F_q(Dv,D^2v)=0$ in $\Omega$;
  \item $u(x)=v(x)+q\cdot x$ is a viscosity solution of the normalized
  homogeneous $p$-Laplace equation;
  \item $u(x)=v(x)+q\cdot x$ belongs to $W^{1,p}_{\mathrm{loc}}(\Omega)$ and is
  weakly $p$-harmonic;
  \item $v\in W^{1,p}_{\mathrm{loc}}(\Omega)$ and
  \begin{equation*}
    -\operatorname{div}\bigl(\left\lvert Dv+q\right\rvert^{p-2}(Dv+q)\bigr)=0
  \end{equation*}
  weakly in $\Omega$.
\end{enumerate}

\label{lem:profile-compactness}
The set $\mathcal K$ is compact in $C(\overline B_{1/2})$, endowed with the uniform norm. For every $h\in\mathcal K$, at least one of the following alternatives holds:
\begin{enumerate}
\item There is $q\in\mathbb R^n$ such that $h+q\cdot x$ is weakly $p$-harmonic in $B_{1/2}$.
\item There is $e\in\mathbb S^{n-1}$ such that
\begin{equation*}
  -\operatorname{tr}\bigl((I+(p-2)e\otimes e)D^2h\bigr)=0
  \quad\text{in }B_{1/2}.
\end{equation*}
\end{enumerate}

Fix $0<\beta<\gamma$ and define $M\coloneqq\left\lVert u\right\rVert_{L^\infty(B_{3/4})}$, which is finite by local boundedness. If $M=0$, the estimate is immediate. Otherwise, define
\begin{equation}\label{eq:scaling}
v(x)\coloneqq\frac{u(3x/4)-u(0)}{2M},\qquad x\in B_1.
\end{equation}
Then $v(0)=0$, $\left\lVert v\right\rVert_{L^\infty(B_1)}\le1$, and \Cref{lem:equivalence} gives $\mathcal F_0(Dv,D^2v)=0$ in $B_1$. 

We set $R_0=1$, $p_0=0$ and $P_0=0$, and construct inductively a sequence $\left( R_k,P_k\right)_k$, with 
$$P_k(x)=v(0)+p_k\cdot x,\qquad k=1,2, \ldots$$
such that
\begin{equation}\label{rachad}
\left\lVert v-P_k\right\rVert_{L^\infty(B_{R_k})} \leq R_k^{1+\beta}, \qquad k\in \mathbb N_0.
\end{equation}
The case $k=0$ follows from our previous choices. Now, suppose $R_k$ and $P_k(x)$ have been constructed satisfying \eqref{rachad}. Define
\begin{equation*}
v_k(x)\coloneqq\frac{v(R_kx)-P_k(R_kx)}{R_k^{1+\beta}},
\end{equation*}
which satisfies $v_k(0)=0$ and, by \eqref{eq:general-shift-update},
\begin{equation*}
\mathcal F_{q_k}(Dv_k,D^2v_k)=0\quad\text{in }B_1,\qquad \textrm{with} \quad  q_k=R_k^{-\beta}p_k.
\end{equation*}
Since we also have $\left\lVert v_k\right\rVert_{L^\infty(B_1)}\le1$, we can apply \Cref{lem:holder-flatness}. It selects a pair $(r_k,b_k)=(\rho_{i_k},b_{i_k})$ for which
\begin{equation*}
\left\lVert v_k-b_k\cdot x\right\rVert_{L^\infty(B_{r_k})}<\frac14r_k^{1+\beta}.
\end{equation*}
Defining $R_{k+1}\coloneqq R_kr_k$ and 
\begin{equation}\label{eq:holder-P-recursion}
P_{k+1}(y)\coloneqq P_k(y)+R_k^{\beta} b_k\cdot y,
\end{equation}
we obtain
\begin{equation*}
\left\lVert v-P_{k+1}\right\rVert_{L^\infty(B_{R_{k+1}})}\le R_{k+1}^{1+\beta},
\end{equation*}
and the induction is complete.

We have
$$\theta^k\le R_k\le\Theta^k\longrightarrow0,$$
where $\theta=\min_i\rho_i$ and $\Theta=\max_i\rho_i$. The finitely many slopes $b_k$ are uniformly bounded. Indeed, let $h_i$ be the profiles selected in the proof of \Cref{lem:holder-flatness}, so that $\ell_{h_i}(x)=h_i(0)+b_i\cdot x$. By \eqref{eq:holder-profile-strict} and $\left\lVert h_i\right\rVert_{C(\overline B_{1/2})}\le1$, it follows that
\[
\begin{aligned}
\rho_i\left\lvert b_i\right\rvert
&=\left\lVert \ell_{h_i}-h_i(0)\right\rVert_{L^\infty(B_{\rho_i})}\\
&\le\left\lVert \ell_{h_i}-h_i\right\rVert_{L^\infty(B_{\rho_i})}
+\left\lVert h_i-h_i(0)\right\rVert_{L^\infty(B_{\rho_i})}\\
&<\frac18\rho_i^{1+\beta}+2<3.
\end{aligned}
\]
Consequently,
\begin{equation*}
\left\lvert b_i\right\rvert\le B_\theta\coloneqq\frac3\theta.
\end{equation*}
Taking gradients in \eqref{eq:holder-P-recursion} yields
\begin{equation*}
p_{k+1}-p_k=R_k^\beta b_k,
\end{equation*}
and thus the sequence $(p_k)$ converges to a vector $p_\infty$.
Since $R_{k+j}\le R_k\Theta^j$ and $\Theta<1/4$, 
\begin{equation}\label{eq:holder-slope-tail}
\left\lvert p_\infty-p_k\right\rvert\le S_{\beta,\theta}R_k^\beta,
\qquad S_{\beta,\theta}\coloneqq\frac{3}{\theta(1-4^{-\beta})}.
\end{equation}

Finally, let $0<\left\lvert x\right\rvert<\theta$ and, by the Archimedean property of the reals, choose $k\ge1$ such that 
$$R_{k+1}< \left\lvert x\right\rvert \leq R_k.$$ 
Since $R_{k+1}\ge\theta R_k$, we have $R_k < \theta^{-1}\left\lvert x\right\rvert$. From \eqref{rachad} and \eqref{eq:holder-slope-tail}, we have
\[
\begin{aligned}
\left\lvert v(x)-v(0)-p_\infty\cdot x\right\rvert
&\le\left\lvert v(x)-P_k(x)\right\rvert+\left\lvert p_k-p_\infty\right\rvert\left\lvert x\right\rvert\\
&\le(1+S_{\beta,\theta})R_k^{1+\beta}\\
&\le(1+S_{\beta,\theta})\theta^{-(1+\beta)}\left\lvert x\right\rvert^{1+\beta}.
\end{aligned}
\]
It follows that $v$ is differentiable at the origin and $Dv(0)=p_\infty$. From \eqref{eq:holder-slope-tail} with $k=0$, we immediately obtain 
\begin{equation*}
\left\lvert Dv(0)\right\rvert\le S_{\beta,\theta}.
\end{equation*}

For each $x_0\in B_{2/3}$, consider
\begin{equation*}
z_{x_0}(y)\coloneqq\frac{v(x_0+y/4)-v(x_0)}{2},\qquad y\in B_1.
\end{equation*}
Since $B_{1/4}(x_0)\subset B_1$, we have $\left\lVert z_{x_0}\right\rVert_{L^\infty(B_1)}\le1$, and $z_{x_0}$ is $p$-harmonic in $B_1$. Applying the estimates to $z_{x_0}$ at the origin gives a uniform gradient bound and uniform affine remainders of order $1+\beta$ at every point in $B_{2/3}$. The standard characterization of $C^{1,\beta}$ by affine approximation gives a uniform $C^{1,\beta}$ estimate for $v$ in $B_{2/3}$. Returning to the original variables via \eqref{eq:scaling} yields \eqref{eq:intro-main-estimate}.

\label{cor:thresholds}
For every $n\ge2$ and $p>2$,
\begin{equation*}
  \alpha_{\mathrm{qual}}(n,p)=\alpha_{\mathrm{quant}}(n,p).
\end{equation*}

\label{infq:small-gradient}
Let $\beta\in(0,1/3)$. There exist $\eta\in(0,1)$ and finitely many radii $\rho_1,\ldots,\rho_N\in(0,1/8)$, depending only on $\beta$, such that every $v\in\mathcal N$ with $|Dv(0)|\le\eta$ satisfies
\begin{equation}\label{infq:improvement}
 \|v\|_{L^\infty(B_{\rho_i})}<\rho_i^{1+\beta},
 \qquad\text{for some }i\in\{1,\ldots,N\}.
\end{equation}

\label{infq:noncritical}
For each $\eta\in(0,1)$ there are $\lambda_\eta\in(0,1/16)$ and $A_\eta<\infty$, depending only on $\eta$, such that every $v\in\mathcal N$ with $|Dv(0)|\ge\eta$ satisfies
\begin{equation}\label{infq:noncritical-estimate}
 |v(y)-Dv(0)\cdot y|\le A_\eta|y|^{4/3},
 \quad y\in B_{\lambda_\eta}.
\end{equation}

Fix $\beta\in(0,1/3)$ and the constants from \Cref{infq:small-gradient}. Set
\[
 \theta=\min_i\rho_i>0,\qquad
 \Theta=\max_i\rho_i<1/8,\qquad
 \lambda=\lambda_\eta,\qquad A=A_\eta.
\]
We first establish a constant $D_\beta$, independent of $v\in\mathcal N$, such that
\begin{equation}\label{infq:taylor}
 \|v-Dv(0)\cdot x\|_{L^\infty(B_r)}
 \le D_\beta r^{1+\beta},\qquad 0<r<1.
\end{equation}

\smallskip
\noindent\emph{Construction of the scales.}
Write $g=Dv(0)$ and start with $R_0=1$, $v_0=v$. As long as $|Dv_k(0)|<\eta$, apply \Cref{infq:small-gradient} to
\[
 v_k(x)=\frac{v(R_kx)}{R_k^{1+\beta}}\in\mathcal N.
\]
It selects $r_k\in\{\rho_1,\ldots,\rho_N\}$ for which
\[
 \|v_k\|_{L^\infty(B_{r_k})}<r_k^{1+\beta}.
\]
With $R_{k+1}=R_kr_k$, invariance~\eqref{infq:invariance} and this inequality imply
\[
 v_{k+1}(x)=\frac{v_k(r_kx)}{r_k^{1+\beta}}
          =\frac{v(R_{k+1}x)}{R_{k+1}^{1+\beta}}\in\mathcal N.
\]
At every constructed scale,
\begin{equation}\label{infq:scale-relations}
 Dv_k(0)=R_k^{-\beta}g,\qquad
 \|v\|_{L^\infty(B_{R_k})}\le R_k^{1+\beta},\qquad
 \theta R_k\le R_{k+1}\le\Theta R_k,
\end{equation}
where the last inequalities apply when the next scale is constructed.

If $g=0$, the iteration never stops and $R_k\le\Theta^k\to0$. For $0<r<1$, choose $j$ with $R_{j+1}\le r\le R_j$. Then $R_j\le r/\theta$, so
\[
 \|v\|_{L^\infty(B_r)}\le R_j^{1+\beta}
 \le\theta^{-(1+\beta)}r^{1+\beta}.
\]
This proves~\eqref{infq:taylor} when $g=0$.

Suppose now that $g\ne0$. The iteration must stop at a finite index $K$: otherwise $R_k\le\Theta^k$ and $|Dv_k(0)|=R_k^{-\beta}|g|\to\infty$, contradicting $|Dv_k(0)|<\eta$. At this first stopping index,
\begin{equation}\label{infq:stopping-gradient}
 \eta\le |Dv_K(0)|\le C_0,
 \qquad |g|<\eta R_j^\beta, \quad 0\le j<K.
\end{equation}
Put $R_*=R_K$. The index $K=0$ is allowed.

\smallskip
\noindent\emph{Radii above the stopping scale.}
If $R_*<r<1$, choose $j<K$ with $R_{j+1}\le r\le R_j$. By~\eqref{infq:scale-relations} and~\eqref{infq:stopping-gradient},
\begin{equation}\label{infq:outer-scales}
 \begin{aligned}
 \|v-g\cdot x\|_{L^\infty(B_r)}
 &\le R_j^{1+\beta}+|g|r\\
 &\le(1+\eta)R_j^{1+\beta}
 \le(1+\eta)\theta^{-(1+\beta)}r^{1+\beta}.
 \end{aligned}
\end{equation}
This range is empty when $K=0$.

\smallskip
\noindent\emph{Radii comparable to the stopping scale.}
For $\lambda R_*\le r\le R_*$, the bounds $\|v_K\|_{L^\infty(B_1)}\le1$ and $|Dv_K(0)|\le C_0$ give
\begin{equation}\label{infq:middle-scales}
 \begin{aligned}
 \|v-g\cdot x\|_{L^\infty(B_r)}
 &\le (1+C_0)R_*^{1+\beta}\\
 &\le (1+C_0)\lambda^{-(1+\beta)}r^{1+\beta}.
 \end{aligned}
\end{equation}

\smallskip
\noindent\emph{Radii below the noncritical scale.}
For $0<r\le\lambda R_*$, apply \Cref{infq:noncritical} to $v_K$. Using $Dv_K(0)=R_*^{-\beta}g$, we find
\begin{equation}\label{infq:inner-scales}
 \begin{aligned}
 \|v-g\cdot x\|_{L^\infty(B_r)}
 &=R_*^{1+\beta}
   \|v_K-Dv_K(0)\cdot x\|_{L^\infty(B_{r/R_*})}\\
 &\le A R_*^{1+\beta}(r/R_*)^{4/3}\\
 &=A r^{1+\beta}(r/R_*)^{1/3-\beta}
 \le A r^{1+\beta}.
 \end{aligned}
\end{equation}
The last inequality uses $r/R_*\le\lambda<1$ and $\beta<1/3$. Thus, no constant depends on $K$ or on $R_*$. Combining the three ranges with the case $g=0$ proves~\eqref{infq:taylor}, with
\begin{equation}\label{infq:taylor-constant}
 D_\beta=
 \max\bigl\{(1+\eta)\theta^{-(1+\beta)},
            (1+C_0)\lambda^{-(1+\beta)},A\bigr\}.
\end{equation}

\smallskip
\noindent\emph{Recentring and comparison of tangent planes.}
Consider first a solution $u$ in $B_1$, and put $M=\operatorname*{osc}_{B_{3/4}}u$, which is finite by continuity on the compact set $\overline B_{3/4}\subset B_1$. If $M=0$, then $u$ is constant on $B_{3/4}$ and the conclusion is immediate. Otherwise, for each $z\in B_{1/2}$ the function
\[
 v_z(x)=\frac{u(z+x/4)-u(z)}{M},\qquad x\in B_1,
\]
belongs to $\mathcal N$, since $B_{1/4}(z)\subset B_{3/4}$. Let $L_z(y)=u(z)+Du(z)\cdot(y-z)$. Rescaling~\eqref{infq:taylor} gives
\begin{equation}\label{infq:uniform-expansions}
 |u(y)-L_z(y)|\le E_\beta M|y-z|^{1+\beta}
 \quad\text{if }|y-z|<1/4,
 \qquad E_\beta=4^{1+\beta}D_\beta.
\end{equation}
For a point on the boundary of a chosen comparison ball, the same bound follows by continuity. Also, $Dv_z(0)=Du(z)/(4M)$ and~\eqref{infq:baseline} imply
\begin{equation}\label{infq:gradient-bound}
 |Du(z)|\le4C_0M, \quad z\in B_{1/2}.
\end{equation}

Let $z,z'\in B_{1/2}$ and $0<d=|z-z'|<1/16$. Set $m=(z+z')/2$. For $y\in B_d(m)$, both $|y-z|$ and $|y-z'|$ are at most $3d/2<1/4$. Hence
\[
 \|L_z-L_{z'}\|_{L^\infty(B_d(m))}
 \le 2E_\beta M(3d/2)^{1+\beta}.
\]
If $P(y)=b+q\cdot(y-m)$ is affine, then
\[
 2d|q|=\operatorname*{osc}_{B_d(m)}P
 \le2\|P\|_{L^\infty(B_d(m))}.
\]
Applying this identity to $P=L_z-L_{z'}$ yields
\[
 |Du(z)-Du(z')|
 \le2(3/2)^{1+\beta}E_\beta M d^\beta.
\]
For $d\ge1/16$, estimate~\eqref{infq:gradient-bound} instead gives
\[
 |Du(z)-Du(z')|\le8C_0M
 \le8C_0\,16^\beta M d^\beta.
\]
We have proved~\eqref{eq:planar-uniform-gradient}, for instance with
\[
 C_\beta=4C_0+
 \max\bigl\{2(3/2)^{1+\beta}E_\beta,\,8C_0\,16^\beta\bigr\}.
\]
For a solution in $B_R(x_0)$, applying this estimate to $x\mapsto u(x_0+Rx)$ gives
\begin{equation}\label{infq:scaled-estimate}
 R\|Du\|_{L^\infty(B_{R/2}(x_0))}
 +R^{1+\beta}[Du]_{C^{0,\beta}(B_{R/2}(x_0))}
 \le C_\beta\operatorname*{osc}_{B_{3R/4}(x_0)}u.
\end{equation}

\label{infq:scope}
If $Du(x_0)=0$, estimate~\eqref{infq:scaled-estimate} and integration along segments give, for $0<r\le R/2$,
\begin{equation}\label{eq:planar-critical-main-estimate}
 \|u-u(x_0)\|_{L^\infty(B_r(x_0))}
 +r\|Du\|_{L^\infty(B_r(x_0))}
 \le C_\beta(r/R)^{1+\beta}\operatorname*{osc}_{B_{3R/4}(x_0)}u,
\end{equation}
after enlarging $C_\beta$.
